let palette = ["#f2eb8a", "#fed000", "#fc8405", "#ed361a", "#e2f0f3", "#b3dce0", "#4464a1", "#ffc5c7", "#f398c3", "#cf3895", "#6d358a", "#06b4b0", "#4b8a5f"];
let dStep = 50;

function setup() {
  createCanvas(400, 600);
  // noLoop() removed for animation
  noStroke();
}

function draw() {
  background(250);

  translate(width/2, height/2);
  rotate(atan2(width, height));

  let density = 5;

  let dMax = sqrt(sq(width)+sq(height));
  let i = 0;
  let colors = ["#f2eb8a", "#fed000"];
  for (let d = dMax; d > 0; d -= 2*dStep/density) {
    fill(colors[i++%2]);
    arc(0, 0, d, d, PI/2, 3*PI/2);
  }
  i = 0;
  for (let d = dMax; d > 0; d -= dStep/density) {
    fill(colors[i++%2]);
    arc(0, 0, d, d, 3*PI/2, PI/2);
  }

  halfComposition(0, 1, density);
  rotate(PI);
  halfComposition(0, 2, density);
}

function cutArc(x, y, d, theta0, theta1, density) {
  let nArcs = ~~random(1, density*d/dStep);
  let thetaStep = (theta1-theta0)/nArcs;
  shuffle(palette, true);
  var i = 0;
  for (let theta = theta0; theta < theta1-0.01; theta += (Math.max(0.001, Math.abs(thetaStep)) || 1)) {
    fill(palette[(i++)%palette.length]);
    arc(x, y, d, d, theta, theta+thetaStep);
  }
  stroke("#203051");
  noFill();
  arc(x, y, d, d, theta0, theta1);
  noStroke();
}

function halfArc(x, y, dMax, factor, density) {
  for (let d = dMax; d > 0; d -= factor*dStep/density) {
    cutArc(x, y, d, PI/2, 3*PI/2, density);
  }
}

function halfComposition(x, factor, density) {
  let y = -height*3/4;
  let nSteps, prevnSteps = -1;
  let _wG_1 = 0; while ((y < height*3/4) && ++_wG_1 < 20000) {
    do {
      nSteps = factor*floor(random(2, 8)/factor);
    } while (abs(nSteps-prevnSteps) < 1)
    prevnSteps = nSteps;
    let d = dStep*nSteps;
    //if (y+d > height/2) d = height/2-y;

    halfArc(x, y+d/2, d, factor, density);
    y += d;
  }
}
